-- v1.0.27 Content Engine 6 Months
-- 26 weeks x 11 channels = 286 executable content assets.
-- Safe/idempotent and linked to Growth Calendar campaigns/LPs where available.
CREATE TABLE IF NOT EXISTS growth_content_assets (
  id UUID PRIMARY KEY,
  calendar_item_id UUID REFERENCES growth_calendar_items(id) ON DELETE SET NULL,
  campaign_id UUID REFERENCES campaigns(id) ON DELETE SET NULL,
  landing_page_id UUID REFERENCES marketing_landing_pages(id) ON DELETE SET NULL,
  campaign_key VARCHAR(120) NOT NULL,
  week_no INT NOT NULL CHECK(week_no BETWEEN 1 AND 26),
  month_no INT NOT NULL CHECK(month_no BETWEEN 1 AND 6),
  channel_key VARCHAR(60) NOT NULL,
  format VARCHAR(100) NOT NULL,
  title VARCHAR(300) NOT NULL,
  hook TEXT NOT NULL,
  primary_copy TEXT NOT NULL,
  script TEXT,
  carousel_slides JSONB NOT NULL DEFAULT '[]'::jsonb,
  cta VARCHAR(240) NOT NULL,
  offer VARCHAR(240),
  seo_keywords JSONB NOT NULL DEFAULT '[]'::jsonb,
  utm_source VARCHAR(120) NOT NULL,
  utm_medium VARCHAR(120) NOT NULL,
  utm_campaign VARCHAR(180) NOT NULL,
  utm_content VARCHAR(180) NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  status VARCHAR(30) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','REVIEW','APPROVED','SCHEDULED','PUBLISHED','ARCHIVED')),
  publish_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(week_no,channel_key)
);
CREATE INDEX IF NOT EXISTS idx_growth_content_week ON growth_content_assets(week_no,month_no);
CREATE INDEX IF NOT EXISTS idx_growth_content_channel ON growth_content_assets(channel_key,status);
CREATE INDEX IF NOT EXISTS idx_growth_content_campaign ON growth_content_assets(campaign_key);

